select TI.id_tipo_instrumento AS "IdTipoInstrumento",TTO.id_tipo_operacion AS "IdTipoOperacion",TTO.accion_orden AS "AccionOrden",TTO.id_tipo_producto AS "IdTipoProducto",TTO.es_venta_corta AS "EsVentaCorta",TTO.es_put_es_call AS "EsPutEsCall" from t_pla_ins_tipo_operacion_tipo_instrumento TI INNER join t_pla_ins_tipo_operacion tto ON TI.id_tipo_operacion = TTO.id_tipo_operacion WHERE TTO.accion_orden IS NOT NULL AND TTO.es_orden = 'S'